<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,HttpException,RuntimeContext};

/** Brand/layout/annotations are report presentation; source evidence never changes. */
final class PhotoReportService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly EvidenceRetentionService $evidence) {}
    private function image(string $base64,int $maxBytes=262144): array {
        $bytes=base64_decode($base64,true);$size=$bytes===false?false:@getimagesizefromstring($bytes);
        if(!$size||!in_array($size[2],[IMAGETYPE_JPEG,IMAGETYPE_PNG],true)||strlen($bytes)>$maxBytes||$size[0]>2048||$size[1]>2048)throw HttpException::unprocessable('Use a JPEG or PNG at most 2048 pixels per side and within the file-size limit.');return ['bytes'=>$bytes,'mime'=>$size[2]===IMAGETYPE_PNG?'image/png':'image/jpeg'];
    }
    private function colour(mixed $value): string {if(!is_string($value)||!preg_match('/^#[a-f0-9]{6}$/Di',$value))throw HttpException::unprocessable('Use a six-digit hexadecimal colour.');return strtoupper($value);}
    public function templates(): array {return $this->db->fetchAll('SELECT template_id,template_name,organisation_name,footer_text,accent_colour,images_per_page,created_at FROM photo_report_templates WHERE company_id=:company ORDER BY template_id DESC LIMIT 100',['company'=>$this->company()]);}
    public function importFieldPhoto(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['photo_id']);$photo=$this->row('report_photos','photo_id',$input['photo_id']??null);if($photo['report_type']!=='incident')throw HttpException::unprocessable('Choose a mobile incident photo.');$old=$this->db->fetch('SELECT evidence_id,purged_at FROM incident_evidence WHERE company_id=:company AND source_report_photo_id=:photo',['company'=>$this->company(),'photo'=>$photo['photo_id']]);if($old){if($old['purged_at']!==null)throw HttpException::conflict('The imported original was removed by retention.');return ['id'=>(string)$old['evidence_id']];}$incident=$this->row('incidents','incident_id',$photo['report_id']);$this->image($photo['image_base64']);$result=$this->evidence->addEvidence(['incident_id'=>$incident['incident_id'],'original_filename'=>'field-incident-photo-'.$photo['photo_id'].'.jpg','file_base64'=>$photo['image_base64'],'description'=>'Imported from mobile incident photo #'.$photo['photo_id'].'; original capture account #'.$photo['created_by_user_id'],'captured_at'=>$incident['occurred_at']]);$this->db->execute('UPDATE incident_evidence SET source_report_photo_id=:photo WHERE company_id=:company AND evidence_id=:id',['photo'=>$photo['photo_id'],'company'=>$this->company(),'id'=>$result['id']]);$this->audit->record('incident_evidence','field_photo_imported',$result['id'],[],[],['source_photo_id'=>$photo['photo_id'],'original_actor'=>$photo['created_by_user_id']]);return $result;
    });}
    public function createTemplate(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['template_name','organisation_name','footer_text','accent_colour','images_per_page','logo_base64']);$logo=empty($input['logo_base64'])?null:$this->image($this->text($input['logo_base64'],140000),100000);
        $this->db->execute('INSERT INTO photo_report_templates(company_id,template_name,organisation_name,footer_text,accent_colour,images_per_page,logo_base64,logo_mime,created_by_user_id,created_at) VALUES(:company,:name,:organisation,:footer,:colour,:layout,:logo,:mime,:actor,:now)',['company'=>$this->company(),'name'=>$this->text($input['template_name']??null,120),'organisation'=>$this->text($input['organisation_name']??null,150),'footer'=>$this->text($input['footer_text']??null),'colour'=>$this->colour($input['accent_colour']??null),'layout'=>$this->number($input['images_per_page']??null,1,2),'logo'=>$logo?base64_encode($logo['bytes']):null,'mime'=>$logo['mime']??null,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('photo_report_template');
    });}
    public function reports(): array {return $this->db->fetchAll('SELECT photo_report_id,site_id,template_id,title,revision,state,created_at,approved_at FROM photo_reports WHERE company_id=:company ORDER BY photo_report_id DESC LIMIT 500',['company'=>$this->company()]);}
    public function createReport(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['site_id','template_id','title','summary']);$site=$this->site($input['site_id']??null);$template=$this->row('photo_report_templates','template_id',$input['template_id']??null);$this->db->execute('INSERT INTO photo_reports(company_id,site_id,template_id,title,summary,created_by_user_id,created_at) VALUES(:company,:site,:template,:title,:summary,:actor,:now)',['company'=>$this->company(),'site'=>$site['site_id'],'template'=>$template['template_id'],'title'=>$this->text($input['title']??null,150),'summary'=>$this->text($input['summary']??null,8000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('photo_report');
    });}
    private function draft(string $id,mixed $revision): array {$report=$this->row('photo_reports','photo_report_id',$id);if($report['state']!=='DRAFT'||$this->number($revision)!==(int)$report['revision'])throw HttpException::conflict('Report is approved or its revision changed. Refresh first.');return $report;}
    private function bump(string $id): void {$this->db->execute('UPDATE photo_reports SET revision=revision+1 WHERE company_id=:company AND photo_report_id=:id',['company'=>$this->company(),'id'=>$id]);}
    private function annotations(mixed $values): string {
        if(!is_array($values)||!array_is_list($values)||count($values)>30)throw HttpException::unprocessable('Use up to 30 annotation shapes.');$out=[];
        foreach($values as$v){if(!is_array($v))throw HttpException::unprocessable('Invalid annotation.');$this->fields($v,['kind','x1','y1','x2','y2','colour','text']);if(!in_array($v['kind']??null,['ARROW','BOX','CIRCLE','TEXT'],true))throw HttpException::unprocessable('Unsupported annotation shape.');$shape=['kind'=>$v['kind'],'colour'=>$this->colour($v['colour']??'#E53935')];foreach(['x1','y1','x2','y2']as$key){$n=$v[$key]??null;if((!is_int($n)&&!is_float($n))||!is_finite((float)$n)||$n<0||$n>1)throw HttpException::unprocessable('Annotation coordinates must be numbers between zero and one.');$shape[$key]=(float)$n;}if($v['kind']==='TEXT')$shape['text']=$this->text($v['text']??null,100);$out[]=$shape;}return json_encode($out,JSON_THROW_ON_ERROR);
    }
    public function addItem(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['expected_revision','evidence_id','caption','sort_order','annotations']);$report=$this->draft($id,$input['expected_revision']??null);$source=$this->row('incident_evidence','evidence_id',$input['evidence_id']??null);$incident=$this->row('incidents','incident_id',$source['incident_id']);if((string)$incident['site_id']!==(string)$report['site_id']||$source['purged_at']!==null)throw HttpException::unprocessable('Choose an available original for an incident at this report site.');$this->image($source['file_base64']);$order=$this->number($input['sort_order']??null,1,20);
        if($this->db->fetch('SELECT item_id FROM photo_report_items WHERE company_id=:company AND photo_report_id=:id AND sort_order=:position',['company'=>$this->company(),'id'=>$id,'position'=>$order]))throw HttpException::conflict('A photo already uses this report position.');$this->db->execute('INSERT INTO photo_report_items(company_id,photo_report_id,evidence_id,caption,sort_order,annotations_json) VALUES(:company,:report,:evidence,:caption,:position,:annotations)',['company'=>$this->company(),'report'=>$id,'evidence'=>$source['evidence_id'],'caption'=>$this->text($input['caption']??null,2000),'position'=>$order,'annotations'=>$this->annotations($input['annotations']??[])]);$created=$this->created('photo_report_item');$this->bump($id);return $created+['revision'=>(int)$report['revision']+1];
    });}
    public function updateReport(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision','title','summary']);$report=$this->draft($id,$input['expected_revision']??null);$this->db->execute('UPDATE photo_reports SET title=:title,summary=:summary,revision=revision+1 WHERE company_id=:company AND photo_report_id=:id',['title'=>$this->text($input['title']??null,150),'summary'=>$this->text($input['summary']??null,8000),'company'=>$this->company(),'id'=>$id]);$this->audit->record('photo_report','draft_updated',$id);return ['revision'=>(int)$report['revision']+1];});}
    public function annotate(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision','caption','annotations']);$item=$this->row('photo_report_items','item_id',$id);$report=$this->draft((string)$item['photo_report_id'],$input['expected_revision']??null);$this->db->execute('UPDATE photo_report_items SET caption=:caption,annotations_json=:annotations WHERE company_id=:company AND item_id=:id',['caption'=>$this->text($input['caption']??null,2000),'annotations'=>$this->annotations($input['annotations']??[]),'company'=>$this->company(),'id'=>$id]);$this->bump((string)$item['photo_report_id']);$this->audit->record('photo_report_item','presentation_updated',$id);return ['revision'=>(int)$report['revision']+1];});}
    public function removeItem(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision']);$item=$this->row('photo_report_items','item_id',$id);$report=$this->draft((string)$item['photo_report_id'],$input['expected_revision']??null);$this->db->execute('DELETE FROM photo_report_items WHERE company_id=:company AND item_id=:id',['company'=>$this->company(),'id'=>$id]);$this->bump((string)$item['photo_report_id']);$this->audit->record('photo_report_item','removed_from_draft',$id);return ['revision'=>(int)$report['revision']+1];});}
    public function detail(string $id): array {return $this->atomic(function()use($id){$report=$this->row('photo_reports','photo_report_id',$id);$report['items']=$this->db->fetchAll('SELECT item_id,evidence_id,caption,sort_order,annotations_json FROM photo_report_items WHERE company_id=:company AND photo_report_id=:id ORDER BY sort_order',['company'=>$this->company(),'id'=>$id]);return $report;});}
    public function itemImage(string $id): array {$item=$this->row('photo_report_items','item_id',$id);$original=$this->evidence->download((string)$item['evidence_id']);return $this->image(base64_encode($original['bytes']));}
    private function validateOriginals(string $id): void {
        foreach($this->detail($id)['items']as$item){$source=$this->row('incident_evidence','evidence_id',$item['evidence_id']);if($source['purged_at']!==null)throw HttpException::conflict('A report original was removed by retention.');$image=$this->image($source['file_base64']);if(!hash_equals($source['sha256'],hash('sha256',$image['bytes'])))throw HttpException::conflict('An original failed its integrity check.');}
    }
    public function approve(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision']);$report=$this->draft($id,$input['expected_revision']??null);if(!$this->db->fetch('SELECT item_id FROM photo_report_items WHERE company_id=:company AND photo_report_id=:id',['company'=>$this->company(),'id'=>$id]))throw HttpException::unprocessable('Add at least one photo before approval.');$this->validateOriginals($id);$this->db->execute("UPDATE photo_reports SET state='APPROVED',revision=revision+1,approved_by_user_id=:actor,approved_at=:now WHERE company_id=:company AND photo_report_id=:id",['actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('photo_report','approved',$id);return ['approved'=>true,'revision'=>(int)$report['revision']+1];});}
    private function escape(mixed $value): string {return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private function overlay(string $json): string {
        $out='<svg viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-label="Report annotations">';foreach(json_decode($json,true,512,JSON_THROW_ON_ERROR)as$a){$x=$a['x1']*1000;$y=$a['y1']*1000;$x2=$a['x2']*1000;$y2=$a['y2']*1000;$c=$this->escape($a['colour']);$style='stroke="'.$c.'" stroke-width="5" fill="none"';if($a['kind']==='BOX')$out.='<rect x="'.min($x,$x2).'" y="'.min($y,$y2).'" width="'.abs($x2-$x).'" height="'.abs($y2-$y).'" '.$style.'/>';elseif($a['kind']==='CIRCLE')$out.='<ellipse cx="'.(($x+$x2)/2).'" cy="'.(($y+$y2)/2).'" rx="'.(abs($x2-$x)/2).'" ry="'.(abs($y2-$y)/2).'" '.$style.'/>';elseif($a['kind']==='TEXT')$out.='<text x="'.$x.'" y="'.$y.'" fill="'.$c.'" font-size="28" font-family="sans-serif">'.$this->escape($a['text']).'</text>';else{$angle=atan2($y2-$y,$x2-$x);$p1=($x2-25*cos($angle-0.45)).','.($y2-25*sin($angle-0.45));$p2=($x2-25*cos($angle+0.45)).','.($y2-25*sin($angle+0.45));$out.='<line x1="'.$x.'" y1="'.$y.'" x2="'.$x2.'" y2="'.$y2.'" '.$style.'/><polyline points="'.$p1.' '.$x2.','.$y2.' '.$p2.'" '.$style.'/>';}}return $out.'</svg>';
    }
    public function printable(string $id): string {
        $report=$this->detail($id);$template=$this->row('photo_report_templates','template_id',$report['template_id']);$site=$this->site($report['site_id']);$e=fn($v)=>$this->escape($v);$layout=(int)$template['images_per_page'];$colour=$this->colour($template['accent_colour']);$html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src &apos;none&apos;; img-src data:; style-src &apos;unsafe-inline&apos;; base-uri &apos;none&apos;; form-action &apos;none&apos;"><meta name="viewport" content="width=device-width"><title>'.$e($report['title']).'</title><style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font:14px system-ui,sans-serif;color:#162437;max-width:900px;margin:auto;padding:24px}header{border-bottom:4px solid '.$colour.';padding-bottom:16px}header img{max-height:60px;max-width:180px}h1{font-size:30px}h2{font-size:19px}.summary,.caption{white-space:pre-wrap;overflow-wrap:anywhere}.sheet{break-before:page}.item{break-inside:avoid;margin:20px 0}.image{position:relative;width:fit-content;max-width:100%;margin:auto}.image img{display:block;max-width:100%;max-height:'.($layout===1?'175':'85').'mm;width:auto}.image svg{position:absolute;inset:0;width:100%;height:100%}.meta,footer{font-size:11px;color:#536175}footer{border-top:1px solid #ccd5df;padding-top:10px;margin-top:20px}.draft{color:#a12222;font-weight:bold}@media print{body{padding:0}.item{margin:10px 0}header{break-inside:avoid}}</style></head><body><header>';
        if($template['logo_base64']){$logo=$this->image($template['logo_base64'],100000);$html.='<img alt="Company logo" src="data:'.$logo['mime'].';base64,'.base64_encode($logo['bytes']).'">';}$html.='<p>'.$e($template['organisation_name']).'</p><h1>'.$e($report['title']).'</h1><p>'.$e($site['site_name']).' · Report #'.$e($id).' · Revision '.$e($report['revision']).'</p><p class="'.($report['state']==='DRAFT'?'draft':'meta').'">'.$e($report['state']).' · '.$e($report['approved_at']??'Pending review').'</p><p class="summary">'.$e($report['summary']).'</p></header>';
        foreach($report['items']as$i=>$item){if($i%$layout===0)$html.='<section class="sheet">';$source=$this->row('incident_evidence','evidence_id',$item['evidence_id']);$original=$this->evidence->download((string)$item['evidence_id']);$image=$this->image(base64_encode($original['bytes']));$html.='<article class="item"><h2>Photo '.($i+1).'</h2><div class="image"><img alt="Evidence photo '.($i+1).'" src="data:'.$image['mime'].';base64,'.base64_encode($image['bytes']).'">'.$this->overlay($item['annotations_json']).'</div><p class="caption">'.$e($item['caption']).'</p><p class="meta">Evidence #'.$e($item['evidence_id']).' · Captured '.$e($source['captured_at']).' UTC<br>Original SHA-256 '.$e($original['sha256']).'</p></article>';if(($i+1)%$layout===0||$i===count($report['items'])-1)$html.='<footer>'.$e($template['footer_text']).' · Page '.(intdiv($i,$layout)+2).'</footer></section>';}
        $this->audit->record('photo_report','printable_exported',$id);return $html.'<footer>Annotations are report overlays. Original evidence bytes are preserved separately. Generated '.gmdate('Y-m-d H:i:s').' UTC.</footer></body></html>';
    }
}
